python - <<'PY'
from boltons.iterutils import split, split_iter, research, default_enter

for make_source in (list, tuple, iter, lambda x: (v for v in x)):
    for values in ([], [1], [1, None, 2]):
        for sep in (None, [None], lambda x: x is None):
            assert split(make_source(values), sep, maxsplit=0) == [values]
            assert list(split_iter(make_source(values), sep, maxsplit=0)) == [values]
assert split('abc', maxsplit=0) == [['a', 'b', 'c']]
source = [1, 2]
assert split(source, maxsplit=0)[0] is not source

shared = [42]
root = {'a': shared, 'b': shared}
query = lambda p, k, v: isinstance(v, int)
assert research(root, query) == [(('a', 0), 42)]
assert research(root, query, cache=False) == [(('a', 0), 42), (('b', 0), 42)]
assert research(root, query, False, default_enter, False) == [(('a', 0), 42), (('b', 0), 42)]
for circular in ([], {}):
    if isinstance(circular, list):
        circular.append(circular)
    else:
        circular['self'] = circular
    assert research(circular, query, cache=True) == []
    for reraise in (False, True):
        try:
            research(circular, query, reraise=reraise, cache=False)
        except RecursionError:
            pass
        else:
            raise AssertionError('expected circular-reference detection')
print('Targeted split and research checks passed')
